<?php require_once __DIR__.'/../includes/db.php';require_once __DIR__.'/../includes/auth.php';require_admin();$booking=null;if($_SERVER['REQUEST_METHOD']==='POST'){$code=strtoupper(trim($_POST['code']));$stmt=$mysqli->prepare('SELECT b.*,u.name,u.vehicle_number,s.slot_number FROM bookings b JOIN users u ON u.id=b.user_id JOIN slots s ON s.id=b.slot_id WHERE b.booking_code=?');$stmt->bind_param('s',$code);$stmt->execute();$booking=$stmt->get_result()->fetch_assoc();if(!$booking)flash('error','No booking found for that QR code.');elseif(isset($_POST['action'])){if($_POST['action']==='entry'&&$booking['status']==='paid'){$now=date('Y-m-d H:i:s');$stmt=$mysqli->prepare("UPDATE bookings SET status='entered',actual_entry=? WHERE id=?");$stmt->bind_param('si',$now,$booking['id']);$stmt->execute();$stmt=$mysqli->prepare("UPDATE slots SET status='occupied' WHERE id=?");$stmt->bind_param('i',$booking['slot_id']);$stmt->execute();flash('success','Entry recorded.');}elseif($_POST['action']==='exit'&&$booking['status']==='entered'){$now=date('Y-m-d H:i:s');$extra=max(0,ceil((strtotime($now)-strtotime($booking['end_time']))/3600));$fine=$extra*50;$stmt=$mysqli->prepare("UPDATE bookings SET status='completed',actual_exit=?,fine_amount=? WHERE id=?");$stmt->bind_param('sdi',$now,$fine,$booking['id']);$stmt->execute();$stmt=$mysqli->prepare("UPDATE slots SET status='available' WHERE id=?");$stmt->bind_param('i',$booking['slot_id']);$stmt->execute();flash('success','Exit recorded. Fine assessed: ₹'.number_format($fine,2));}else flash('error','This action is not available for the booking status.');header('Location: scan.php');exit;}}$page_title='QR entry and exit';require __DIR__.'/../includes/header.php'; ?>
<div class="row justify-content-center"><div class="col-lg-7"><div class="card shadow-sm border-0"><div class="card-body p-4"><h2>QR entry / exit</h2><p class="text-muted">Scan into a QR reader, or enter the pass code manually for this demo.</p><form method="post" class="input-group"><input class="form-control" name="code" value="<?=e($_POST['code']??'')?>" placeholder="PE-XXXXXXXX" required><button class="btn btn-primary">Find booking</button></form><?php if($booking):?><hr><h5><?=e($booking['booking_code'])?> · <?=e($booking['slot_number'])?></h5><p><?=e($booking['name'])?> · <?=e($booking['vehicle_number'])?><br>Status: <b><?=e($booking['status'])?></b></p><form method="post" class="d-flex gap-2"><input type="hidden" name="code" value="<?=e($booking['booking_code'])?>"><?php if($booking['status']==='paid'):?><button class="btn btn-success" name="action" value="entry">Record entry</button><?php elseif($booking['status']==='entered'):?><button class="btn btn-danger" name="action" value="exit">Record exit & calculate fine</button><?php endif;?></form><?php endif;?></div></div></div></div><?php require __DIR__.'/../includes/footer.php'; ?>
